import 'dart:convert';import 'package:shared_preferences/shared_preferences.dart';import 'local_database.dart';
class LegacyDataMigration{
 static Future<void> run(LocalDatabase database)async{final prefs=await SharedPreferences.getInstance();if(await database.getPreference('legacy_preferences_migrated')=='1')return;final raw=prefs.getString('pawpal.local.v1');if(raw==null){await database.setPreference('legacy_preferences_migrated','1');return;}final decoded=jsonDecode(raw);if(decoded is! Map)throw const FormatException('Legacy PawPal data is invalid.');final pets=(decoded['pets'] as List? ?? const []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();final petIds=pets.map((e)=>e['id']?.toString()??'').toSet();final tasks=(decoded['tasks'] as List? ?? const []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).where((e)=>petIds.contains(e['petId']?.toString())).toList();final logs=(decoded['logs'] as List? ?? const []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).where((e)=>petIds.contains(e['petId']?.toString())).toList();
 await database.db.transaction((txn)async{for(final pet in pets){final id=pet['id']?.toString()??'';if(id.isEmpty)continue;final value=<String,dynamic>{'id':id,'name':pet['name']?.toString()??'Pet','species':pet['species']?.toString()??'Dog','breed':pet['breed']?.toString()??'','birthDate':pet['birthday']?.toString()??'','ageEstimated':0,'sex':'','weightValue':double.tryParse(pet['weight']?.toString()??''),'weightUnit':decoded['units']=='Metric'?'kg':'lb','photoPath':'','adoptionDate':'','notes':pet['notes']?.toString()??'','vetName':'','vetPhone':'','archived':0};await txn.insert('pets',{'id':id,'pet_id':null,'payload':jsonEncode(value),'updated_at':DateTime.now().toIso8601String()});}
 for(final task in tasks){final id=task['id']?.toString()??'';if(id.isEmpty)continue;final repeat=(task['repeat']?.toString()??'Once').toLowerCase();final value=<String,dynamic>{'id':id,'petId':task['petId'],'title':task['title']?.toString()??'Care task','category':task['type']?.toString()??'Custom','dueAt':task['due']?.toString()??DateTime.now().toIso8601String(),'repeat':repeat=='once'?'once':repeat,'weekdays':'','intervalDays':1,'monthEndPolicy':'last_day','note':task['note']?.toString()??'','enabled':1,'completed':task['done']==true?1:0,'snoozedUntil':null};await txn.insert('reminders',{'id':id,'pet_id':value['petId'],'payload':jsonEncode(value),'updated_at':DateTime.now().toIso8601String()});}
 for(final log in logs){final id=log['id']?.toString()??'';if(id.isEmpty)continue;final value=<String,dynamic>{'id':id,'petId':log['petId'],'type':log['type']?.toString()??'Custom','title':log['title']?.toString()??'Care note','at':log['at']?.toString()??DateTime.now().toIso8601String(),'value':null,'unit':'','note':log['detail']?.toString()??'','attachmentPath':''};await txn.insert('care_logs',{'id':id,'pet_id':value['petId'],'payload':jsonEncode(value),'updated_at':DateTime.now().toIso8601String()});}
 final selected=decoded['selected']?.toString();if(selected!=null&&petIds.contains(selected))await txn.insert('preferences',{'key':'selected_pet','value':selected});final unit=decoded['units']?.toString()=='Metric'?'kg':'lb';await txn.insert('preferences',{'key':'weight_unit','value':unit});await txn.insert('preferences',{'key':'legacy_preferences_migrated','value':'1'});});
 }
}
